def solve(g):
    g=[r[:] for r in g]; R,C=len(g),len(g[0])
    # find band: a full row or column of same nonzero color
    band=None; bdir=None
    for r in range(R):
        if len(set(g[r]))==1 and g[r][0]!=0: band=('row',r); bdir='up' if r>0 else 'down'
    if band is None:
        for c in range(C):
            col=[g[r][c] for r in range(R)]
            if len(set(col))==1 and col[0]!=0: band=('col',c); bdir='left' if c>0 else 'right'
    bk,bi=band
    # extract shapes: connected nonzero non-band components
    seen=[[False]*C for _ in range(R)]; shapes=[]
    for r in range(R):
        for c in range(C):
            if g[r][c] and not seen[r][c] and not (bk=='row' and r==bi or bk=='col' and c==bi):
                col=g[r][c]; stack=[(r,c)]; comp=[]
                seen[r][c]=True
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<R and 0<=nx<C and not seen[ny][nx] and g[ny][nx]==col and not (bk=='row' and ny==bi or bk=='col' and nx==bi):
                            seen[ny][nx]=True; stack.append((ny,nx))
                shapes.append(sorted(comp))
    dr,dc={'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}[bdir]
    def dist(sh):
        if bk=='row': return min(abs(r-bi) for r,c in sh)-1
        else: return min(abs(c-bi) for r,c in sh)-1
    shapes.sort(key=lambda sh:(dist(sh), sh[0]))
    out=[[-0 if v==0 else v for v in row] for row in g]
    # clear non-band cells
    for r in range(R):
        for c in range(C):
            if not (bk=='row' and r==bi or bk=='col' and c==bi): out[r][c]=0
    occ=set()
    for r in range(R):
        for c in range(C):
            if (bk=='row' and r==bi) or (bk=='col' and c==bi): occ.add((r,c))
    def blocked(sh):
        return all(p in occ or (bk=='row' and p[0]==bi) or (bk=='col' and p[1]==bi) or not (0<=p[0]<R and 0<=p[1]<C) for p in []) # placeholder
    for sh in shapes:
        # move as far as possible toward band
        cur=sh
        while True:
            nxt=[(r+dr,c+dc) for r,c in cur]
            if any((r,c) in occ or (bk=='row' and r==bi) or (bk=='col' and c==bi) for r,c in nxt):
                break
            cur=nxt
        for (r,c),v in zip(cur,[g[rr][cc] for rr,cc in sh]):
            out[r][c]=v; occ.add((r,c))
    return out

